SELECT r.id FROM (WITH c(a, b) AS (VALUES (1, NULL::int)) SELECT x.a AS n FROM c AS x(b, a)) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT s.id FROM (VALUES (NULL::int)) p(n) CROSS JOIN LATERAL (SELECT r.id FROM (VALUES (1)) p(n), (SELECT p.n AS n) q, LATERAL (SELECT id FROM probe LIMIT q.n) r) s;
SELECT s.id FROM (VALUES (NULL::int)) p(n) CROSS JOIN LATERAL (SELECT r.id FROM (VALUES (1)) p(n), LATERAL (SELECT p.n AS n) q, LATERAL (SELECT id FROM probe LIMIT q.n) r) s;
SELECT r.id FROM (SELECT v.n FROM (VALUES (1)) v(n) GROUP BY ROLLUP (v.n)) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM (SELECT v.n FROM (VALUES (1)) v(n) GROUP BY CUBE (v.n)) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM (SELECT v.n FROM (VALUES (1)) v(n) GROUP BY GROUPING SETS ((v.n), ())) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM (SELECT GREATEST(v.n, 0) AS n FROM (VALUES (1)) v(n) GROUP BY ROLLUP (v.n)) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM (SELECT v.n FROM (VALUES (1)) v(n) GROUP BY v.n) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM (SELECT 1 AS n UNION ALL SELECT 2 AS other) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM (SELECT 1 AS n, 2 AS spare) p(cap) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.cap) r;
SELECT r.id FROM (SELECT 1 AS n, 2 AS n) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM (SELECT 1 AS n) p(a, b) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.a) r;
SELECT r.id FROM (SELECT * FROM (VALUES (1)) v(n)) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
SELECT r.id FROM ((SELECT 1 AS n)) p CROSS JOIN LATERAL (SELECT id FROM probe LIMIT p.n) r;
WITH RECURSIVE c(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM c WHERE n < 3) SELECT r.id FROM c CROSS JOIN LATERAL (SELECT id FROM probe LIMIT c.n) r;
SELECT q.id FROM budgets CROSS JOIN LATERAL (((SELECT id FROM probe LIMIT budgets.cap))) q;
SELECT r.id FROM LATERAL (SELECT 1 AS n) d RIGHT JOIN (VALUES (NULL::int)) extra(n) ON true CROSS JOIN LATERAL (SELECT id FROM probe LIMIT d.n) r;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM probe LIMIT f.row_limit::int) x;
SELECT x.id FROM unnest($1::int[]) f(row_limit) CROSS JOIN LATERAL (SELECT id FROM (probe JOIN probe AS p2 ON true) LIMIT f.row_limit) x;
